-// src != 0, shift != 0, base != 0
-instruct decodeNKlass_notNull_addBase_ExEx(iRegPdst dst, iRegNsrc src) %{
+instruct decodeNKlass_notNull_addBase_Ex(iRegPdst dst, iRegNsrc src) %{
@@ -6786,1 +6698,1 @@
